// src/pages/notifications/NotificationDetailPage.jsx
import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { fetchAlertDetail } from '../../api/NotificationsApi';

function NotificationDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();

  const [notification, setNotification] = useState(location.state?.notification ?? null);
  const [loading, setLoading] = useState(!location.state?.notification);
  const [error, setError] = useState(null);

  useEffect(() => {
    let mounted = true;

    const load = async () => {
      if (notification) return;
      setLoading(true);
      setError(null);
      try {
        const data = await fetchAlertDetail(id);
        if (mounted) setNotification(data);
      } catch (e) {
        if (mounted) setError(e);
      } finally {
        if (mounted) setLoading(false);
      }
    };

    load();
    return () => { mounted = false; };
  }, [id, notification]);

  return (
    <div className="page-container">
      <h1>알림 상세</h1>

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>에러: {String(error.message || error)}</p>}

      {!loading && !error && !notification && (
        <p>알림 데이터를 찾을 수 없습니다.</p>
      )}

      {!loading && !error && notification && (
        <div className="notification-detail-card" style={{ padding: 12, border: '1px solid #eee', borderRadius: 8 }}>
          <p><strong>ID:</strong> {notification.id}</p>
          <p><strong>시간:</strong> {notification.collectedAt}</p>
          <p><strong>라벨:</strong> {notification.aiLabel || '(없음)'}</p>
          <p><strong>점수:</strong> {notification.aiScore ?? '(없음)'}</p>
          <p><strong>이벤트:</strong> {notification.eventType}</p>
          <p style={{ wordBreak: 'break-all' }}><strong>경로:</strong> {notification.path}</p>

          <hr />

          <p><strong>AI 상세 설명</strong></p>
          <pre style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
            {notification.aiDetail || '(상세 내용 없음)'}
          </pre>
        </div>
      )}

      <div style={{ marginTop: 12 }}>
        <button className="btn" onClick={() => navigate('/notifications')}>
          알림 목록으로 돌아가기
        </button>
      </div>
    </div>
  );
}

export default NotificationDetailPage;
